section.para:
When auto-generating physical volumes, the
spacePolicy option controls how much space
from the target devices is used. Two policies are available:

section.programlisting:
"storage": {
  "drives": [
    {
      "partitions": [
        {
          "alias": "pv",
          "id": "lvm",
          "size": { "min": "50 GiB" },
          "encryption": {
            "luks2": {
              "password": "my secret passphrase",
              "tpm": true
            }
          }
        }
      ]
    }
  ],
  "volumeGroups": [
    {
      "name": "system",
      "physicalVolumes": ["pv"],
      "logicalVolumes": [
        {
          "name": "root",
          "size": { "min": "30 GiB" },
          "filesystem": { "path": "/", "type": "btrfs" }
        },
        {
          "name": "swap",
          "size": "2 GiB",
          "filesystem": { "path": "swap" }
        }
      ]
    }
  ]
}
